// src/actix/api/cluster_api.rs L203-260 (excerpt) — handler:
#[get("/cluster/telemetry")]
async fn get_cluster_telemetry(
    dispatcher: web::Data<Dispatcher>,
    ActixAuth(auth): ActixAuth,
    params: Query<ClusterTelemetryParams>,
) -> HttpResponse {
    ...
    let timeout = params.timeout.unwrap_or(DEFAULT_GRPC_TIMEOUT.as_secs()); // default 60 (transport_channel_pool.rs L25: Duration::from_secs(60))
    let all_peers: Vec<_> = channel_service
        .id_to_address
        .read()
        .keys()
        .copied()
        .collect();
    let mut futures = all_peers
        .into_iter()
        .map(|peer_id| {
            channel_service
                .with_qdrant_client(peer_id, |mut client| {
                    let request = grpc::GetTelemetryRequest {
                        collections_selector: collections_selector.clone(),
                        details_level,
                        timeout,
                    };
                    async move { client.get_telemetry(request).await }
                })
                .map_err(move |err| (peer_id, err))
        })
        .collect::<FuturesUnordered<_>>();
    let mut telemetries = Vec::with_capacity(futures.len());
    ...
    let distributed_telemetry =
        DistributedTelemetryData::resolve_telemetries(access, telemetries, missing_peers)?;

// src/common/telemetry_ops/distributed_telemetry.rs L150-158 — the 500 origin:
impl DistributedTelemetryData {
    pub fn resolve_telemetries(
        access: &Access,
        telemetries: Vec<TelemetryData>,
        missing_peers: Vec<PeerId>,
    ) -> StorageResult<Self> {
        // Use the telemetry from node with highest term/commit
        let base_telemetry = newest_telemetry(&telemetries)
            .ok_or_else(|| StorageError::service_error("Could not get telemetry from cluster"))?; // <- empty telemetries vec => HTTP 500

